INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('75ad20db-53b8-4e9d-86cb-601a7808bfbf', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "8c4ade69-50ec-4ed7-a4fd-184eed8423a2", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "21d1ff40-dcac-4370-80bb-f6eb8ae66693", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "fd637a76-6a40-4493-bce2-545806e51a9a", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "4bb68ccb-8b62-4c1d-b4be-44d44a371b1e", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "6b174741-ba13-475e-a6f8-5ee823b1f327", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "6517ca43-aa3c-4d9f-b89b-dc737dfc0941", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "06468ce4-b18c-4fa3-bab6-3c85c27b7ee0", "text": "Igaz", "isCorrect": true}, {"id": "d1b070c2-60dc-4f40-9aa0-dff05ff1834e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b266701-d8d5-45dd-a10d-bc4de3031f06", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "3ad71c55-6bed-4c46-911c-b4bd988027e1", "text": "Igaz", "isCorrect": true}, {"id": "ba5b8a9e-408c-4582-a8ba-8b36b9fb68b5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea8e96d5-d5e7-4647-9524-ebd4526451f7", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9186b7e8-6854-40ad-badc-270a77346bb2", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "3c5c79f5-0728-4882-b900-a8b516f38825", "text": "Igaz", "isCorrect": true}, {"id": "036d4013-e82d-40b4-b337-221ada72d6d0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31749750-ac81-4c84-a08d-a5d3969781e8", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "38eca3a5-1963-42ae-8663-6dbb5f5074e5", "text": "Igaz", "isCorrect": true}, {"id": "2614b241-6ca3-421e-9700-6d1b38f21fed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25354e89-a522-4f93-9be3-5feab2631523", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('9f0da469-96d6-4c0f-b9eb-467983230412', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "cbdb307e-1681-4ffe-bc4b-ff005faad93f", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6cb85fb9-57f8-406a-91bf-509c1157a884", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "9c9ce4b8-bfe4-4a6d-94a7-ce466f8592f6", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "a1d4f139-3adf-4ba9-a53b-f299b8985c65", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "f68f67ef-8a33-4099-9b42-442bde9222d3", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "55901a2e-f5aa-4dd3-a3bd-756e9c525b9f", "text": "Igaz", "isCorrect": true}, {"id": "b1540edb-e35e-4865-9903-57b3ece1dc4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c6bb8f70-18eb-422e-a734-e7ed680b8c81", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "88002da5-d81d-45c0-b1ad-5af907420dcb", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "d85c9971-14e6-43f2-b177-e75c0259642c", "text": "Igaz", "isCorrect": true}, {"id": "9a61cceb-374a-459f-9fff-0e6289069d8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('4833906a-016b-4c4c-b572-eeef18491b91', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f5946b84-731c-4500-8158-b3c1f7538459", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "36c69e81-6c66-4761-9b2f-61bd172bb89a", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "17490d6f-0fe7-4fca-8669-96cf648d5612", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "9239010e-70fa-4601-a369-42729692fa85", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "dd17735f-c368-455c-9c70-cc43312b913c", "text": "Igaz", "isCorrect": true}, {"id": "17623a74-d821-404f-b97d-f1ca5750ed3d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6faf62db-e3bd-454d-8ec6-0868fa069344", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "dc5308e0-0168-40b4-ac91-3550436e37b5", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "cc2a6bed-f1c9-4290-9708-bbc6f493900f", "text": "Igaz", "isCorrect": true}, {"id": "ed6fd02c-0725-4ea8-8aac-f85a65015a5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d10bf95-84fa-4285-823e-60b88ed826ed", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW()),
('7fd470e6-99ed-45b0-8a99-93b433335b46', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "51c2de0d-d209-4145-bbb9-300b537ee920", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "7d0057d2-1f8f-4eca-b9fd-37477d3f07af", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "35366c01-5688-4469-a918-0a41da22770a", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "35780ca0-cb1a-440d-bdda-7a7fcb05d599", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "07b39d0d-a878-4d8d-ae43-dfe1cbf5f5c2", "text": "Igaz", "isCorrect": true}, {"id": "e4e9c0d9-0599-4b31-ae21-9c92ed64e98a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b76f60ac-ea4c-4d68-8c1e-1536a9e8d8e2", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "132b28ba-f23b-4e16-a95d-e3bbf5bdc997", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "cbb33afe-1cec-4825-bf93-382f99404940", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "faa1a2d1-39aa-47e7-b89e-28b9b03f5a57", "text": "Igaz", "isCorrect": true}, {"id": "e2634638-9bb3-4c88-a091-48e86f9db7be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('f82ac67f-a8f1-4d72-b9b7-890e238edacf', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e2351f85-6fd1-4065-a34b-96bec10ab402", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "d38caf38-e9a4-4c2a-9155-6c177ac0ca3a", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "edf4f74c-e0d6-473e-ac9b-30b89ccd0afb", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "a1442b52-52fd-4709-9a7c-3076b9049378", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "9651a8b3-1c3a-4f63-b7c5-3b7ab3d6bc23", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "bb9e8597-f68f-468b-9677-e83cac034204", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "3c744035-2f0a-431d-996b-a4ac936d4deb", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "067d7dff-caf0-43b6-bf04-d9867a1aafd0", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "1a6db44c-3dc4-46fc-a9c0-20495a18ba5d", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "764c9b0c-d638-4abd-8a40-d61dad290730", "text": "Igaz", "isCorrect": true}, {"id": "d22e676c-cfd6-4e1f-9664-af04d01a3af8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0f16f6e-ac19-48cb-bf65-5c065ee7f83a", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()),
('ec13351c-3936-42fa-b5d5-fe306fee81f2', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e2abb2a3-68f4-420d-beff-aaef33697870", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "71d14222-67ab-4097-8e13-345863dbbfd5", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "181eb589-fc7a-4259-9f2d-200721d66edf", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "95a820e2-cb27-4774-bab9-0241afdef1d6", "text": "A számláló írása", "isCorrect": false}, {"id": "1ee9d0bc-1c89-4525-b79e-e1c550b014bf", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "8e0d96ec-d7b9-422c-acdd-bd409a7ce011", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "c69b654a-5f84-4b21-9439-7b7321bbffef", "text": "Igaz", "isCorrect": true}, {"id": "d8427d48-3158-4376-b35d-0cf85e8c8122", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e24cb64-3992-4e54-b039-b0582e5a122d", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "796b9fb1-3a5c-4660-8cc9-cd5d0c34336c", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "072309ce-2ec4-4d24-9af8-4323918e5802", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "37e69bd8-cb71-4e4d-a7ca-44556aa83b83", "text": "Igaz", "isCorrect": true}, {"id": "071be2f8-ebae-47ce-99c0-7596213104a8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "69d117f5-b4e7-469c-adff-98e4b3fac172", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ff73b221-af47-41a2-bf8e-590e7407762b", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "b6c2186d-40fb-4f69-b435-f923a455e3c4", "text": "Igaz", "isCorrect": true}, {"id": "850c2d82-cbcc-4bba-aba5-13e67bc7f035", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('4c085d50-7f9b-43a0-822b-644d773bc342', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "5732e914-0559-4830-87df-3ba833c7c901", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "3065b01d-f86e-4b2a-ac81-706e17fe8244", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "e2663d1b-6e12-4616-92f3-b9f215b0bb1c", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "82f056e4-f33c-4cf2-badf-76088e36f5f3", "text": "Számok törlése", "isCorrect": false}, {"id": "3c50d00b-a4fa-4edb-9178-597ddda16975", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "bb448462-35bb-43d8-826e-439b98f0a9af", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "5d291ba7-cbe1-4ae9-b920-8596308c75c9", "text": "Igaz", "isCorrect": true}, {"id": "497d04d1-34c4-49e3-9ebb-8299fc1a6aed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "83777dc0-5337-4613-bca8-303fe745a9f9", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "e58dc8fc-b5ec-4a8a-be87-80b502ed73ac", "text": "Alvás", "isCorrect": true}, {"id": "61032a19-6f41-4942-8d0b-eda6d4366c73", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "5f5dd090-8eba-4262-8ba2-bb0d6cbb757f", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "c7cff748-d1e7-49d2-9014-00da90d45224", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "fa4b6bf7-d083-4cce-819f-ebafd122f50e", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "a84e8d80-579c-4490-b131-ab7fd62b0d39", "text": "Igaz", "isCorrect": true}, {"id": "6b15cfb6-07ea-49e9-b00d-d7c49ff51247", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c91918b3-6330-40f7-a4ea-a2ac85ac8a78", "text": "Hány válaszlehetőség van egy ''igen/nem'' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "40aa48c5-622e-4a4b-985a-5cb22fa6df75", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "3af0efd5-ba1d-49a0-9d65-df99f08d53fb", "text": "Igaz", "isCorrect": true}, {"id": "d7daa93d-511e-4a3a-805a-2ac171f55157", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f4875069-d355-4cbb-97c8-55574a155fcd", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "d5d58648-2d8e-4c50-8b8a-8bd56f77d87a", "text": "Igaz", "isCorrect": true}, {"id": "e829a0dc-2c94-4e3a-9295-9a8d33e38782", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('c04f8285-8899-49a8-b3e6-53706a75c30d', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "5d715ac6-289c-43b5-90ac-1dfcb5d5edef", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "0cc28d03-5310-489a-9617-fd71b7481444", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "3f1bdf90-568e-4d51-803b-29e4613e0dfd", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "d62c8772-2843-4085-a2d5-9aeb0a244a77", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "67264694-76de-4982-95de-0b2eba77cca4", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "7159c1d1-9279-4357-b6d8-df27a0b8f3a1", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "5531cd3b-662c-4040-a90e-c595bcdcadbd", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "19516880-2307-4cc7-ac1c-e39d99cb3f34", "text": "Számok összeadására", "isCorrect": false}, {"id": "363fd1ef-bb9f-48fa-93d2-b6f0b287162a", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "f7e521d3-c359-4df1-b2e5-da80ef64c450", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "df6249e2-4e7d-4933-95b2-2bc3bfc8c29a", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6f9f7390-1d7c-4c4b-a457-d1d43b7af405", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "9fb45d17-ab71-49c7-b90b-ff4fcef65ea4", "text": "Igaz", "isCorrect": true}, {"id": "22013857-0d93-40e2-a659-54e04aef7e70", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "588bf1f3-6b88-4137-b47e-fd449335e156", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "7f06b580-bf60-4b0d-8955-725b11fea4e3", "text": "Igaz", "isCorrect": true}, {"id": "2230f0bc-4a16-4e91-98f8-d236eb43e1b3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04c7d4dd-8d55-452e-bf2b-f5781ce91269", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "4e6a65da-2516-492a-8e5f-1379dddc4917", "text": "Igaz", "isCorrect": true}, {"id": "b2a960e3-47c7-4f2b-9aaf-427eb8682f78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21f9c10b-98a3-40ba-9cda-d7ec4bf160eb", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW()),
('ae4e32da-31b8-4d16-911a-e4c886f2a4b1', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "fe9ef936-7377-4986-b1e2-cdf17cd06945", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "2d4af40a-c235-4903-aed3-7f8a0a3b2412", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "cd799398-43bf-4e04-a258-7048564f2dbe", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "382c8b7c-eea1-449f-8ddc-673aad50c763", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "41df6ac1-5824-473c-a134-a102a5826475", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "aff40c65-3506-42b9-995f-ad1b48af66a3", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "f69e353a-e7d7-48e3-a502-d6c892f3bce4", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "5a659367-3059-4841-a286-5ccdb5b98807", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "88aa1334-8632-4e33-b128-71f2f29b1ae2", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "d932a0db-1c99-42e8-8a6d-aaa5c3535d88", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "6c14d23c-1a52-4975-beb8-39c803294a33", "text": "Igaz", "isCorrect": true}, {"id": "4d9cf5a7-644e-4ae6-ac16-ddec0a9b1027", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f3820bd-62e8-4cb1-87a2-6f07b47a25fa", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "6e2e3b25-7697-4648-bbca-ac2c75049ddd", "text": "Igaz", "isCorrect": true}, {"id": "e5c0728d-ccd1-4e4d-99a1-6cf059c8c1a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('bf5ee704-30f7-487d-bc23-b900fbe9bd9a', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "defe38be-c43b-40c7-bfca-9f1136fc94cd", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "1e4c604d-9d29-4e0c-a71e-02439bcdbb99", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "5f3dd4f4-5675-451a-b963-1455d5474ffe", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "f920bf29-7126-48c3-8537-37ab2b366e16", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "610b1cc1-4d13-4ac7-93a5-949907a503b3", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "8705282b-45f2-4f48-8a96-5cf7ecb3a6ff", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "50b86e84-927b-479e-93dd-60de1d717ab0", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "b0cff6d6-b0f2-40be-9665-e03daa263903", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "87c5882c-417b-434a-b3a2-925952201679", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "43ca3979-6929-43d7-888d-8619dd219ede", "text": "Igaz", "isCorrect": true}, {"id": "5961d4f9-7df1-4165-a049-7bdde34cae77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4724d84d-68b2-42fe-876f-09acd45b4803", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "74e0cea9-11df-46a7-ac00-302c57a311d2", "text": "Igaz", "isCorrect": true}, {"id": "cb578a33-e0d2-4e16-9604-02c68f5d65fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec3cb171-f206-4ad0-8b99-0e2b02ea0ad6", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('91a7877d-6d9b-4ed0-b336-c1269efffd68', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "15bbdd55-f7b0-42e8-b067-645fdb6827ef", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "63212233-93f6-493c-a92e-be1b68f3dc43", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "b0bba47a-8d92-412e-a6ce-9aff7f249616", "text": "1 a 2-ből", "isCorrect": false}, {"id": "384d4094-cfe3-41f3-bb9a-f9e734393fbe", "text": "100%", "isCorrect": false}, {"id": "f3cb73e1-b50c-49f0-89d7-9fef84a87e89", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "759cc92d-0047-4920-90c1-fe78e31546c2", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "34d1ea2a-bdf2-4a7f-a4d7-7000a2c74005", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "9666464d-205b-48da-b3ca-b6d7133bd52a", "text": "1/6", "isCorrect": false}, {"id": "89da597f-4199-4f81-9fbf-438731a783ec", "text": "2/6", "isCorrect": false}, {"id": "00d1582b-a0f0-457e-88f3-9fc7e2b8bdc2", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "595c7fae-3e31-448d-8851-f98ab085443a", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "4dd32e71-a920-4e36-84b1-771c7e2298d0", "text": "Igaz", "isCorrect": true}, {"id": "0f160da2-30ab-4231-8750-5469850f4eb5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1d37ac8-446a-491b-bbc7-7e3ef07d65a5", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "0d78e8c1-49f6-43ad-9e85-dc86e0c760db", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "7c40996b-fee4-45c9-b221-83de11b5bbcf", "text": "Biztos esemény", "isCorrect": false}, {"id": "8f45f7ae-f7d7-4683-8cdb-40031dbc0303", "text": "Lehetséges", "isCorrect": false}, {"id": "3858753c-ef8c-4bfb-96ab-236ced4dc91d", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "c86db158-8015-424f-a9f4-0c3fd4221dc1", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "39da0965-b9c9-45e5-96d2-f85679f779b7", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "c8d3517c-2b13-4cd8-a613-312377e24175", "text": "Lehetetlen", "isCorrect": false}, {"id": "e1553474-3810-4815-b7a5-a15cdf1b3adc", "text": "Kétes", "isCorrect": false}, {"id": "4cbb4053-24ab-46a9-99da-3be8cce969bb", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "6727850c-e255-48df-a9e3-4446e109e805", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "40c56352-fd6c-4b79-a90f-e303f062cb74", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "7a24858b-8e08-487b-ba04-57a56d2c0614", "text": "Igaz", "isCorrect": true}, {"id": "2f292a0e-02ce-47ef-b417-d082082e6e35", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('8d356ee4-4e9d-44f9-9815-381371403c5b', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "141a6579-575b-4bf3-b5ba-3b61d3786508", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "e24c4893-9341-46f3-bf17-1a97a50e3073", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "dec94a40-5379-49e2-91d3-584485242dd8", "text": "1/4", "isCorrect": false}, {"id": "14429faf-25b4-4d41-a655-929587b65fc3", "text": "100%", "isCorrect": false}, {"id": "036580d7-6593-4585-a20c-5addc3fe765d", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "0f018425-7591-493e-81aa-4f46b1a50ac7", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "f9744e1a-c26a-44ef-b804-068322ce8d18", "text": "Igaz", "isCorrect": true}, {"id": "2aa88d60-0b19-4b7a-b2c3-254d2d644698", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70cb2585-8336-4367-ac99-4d19914bc423", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e6505437-c4c1-49d3-9b9c-58c7df94be84", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "b4f71022-65d8-46c8-b574-2b0e36c99619", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "f32c0188-3514-4f73-91ef-990a1ad7bafc", "text": "Igaz", "isCorrect": true}, {"id": "b9b36454-b1ac-4c67-aef8-e6902e21875e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "026a297f-0a7a-4207-b33a-0e28f3d52ce6", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "971a6bc2-87f1-4e78-9a13-34f1dda16712", "text": "Igaz", "isCorrect": true}, {"id": "7aab9836-2c58-497e-b170-2bdaab196e60", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c97fea4c-176f-49ac-826a-8daf381e8e2c", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "505c4659-5594-4f63-a563-7f44a4f737c7", "text": "Igaz", "isCorrect": true}, {"id": "e6a34d7c-2b26-4ad6-8585-0ab8a529fa29", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('f723df99-21df-4ea5-b730-1838de170804', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "bb58e9bc-ac61-4fca-99fc-e565cc857fcb", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "fb9a8cf4-a94e-41f8-8733-5722e671118b", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "6daf5634-36dc-47c7-a71b-c7c66b8477e6", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "0a85edd2-ce00-425b-b13a-8fe59d854abf", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "e762897a-37e7-4491-a0ad-d519484234c5", "text": "Igaz", "isCorrect": true}, {"id": "d44e1581-d467-4a21-8e82-5ef227c8da51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfa9339a-14a1-4931-b9aa-05973744d995", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "75202eb3-6a1b-409e-a6d5-f63c3aa29dfe", "text": "Igaz", "isCorrect": true}, {"id": "b36b4cb2-1948-4286-8b6d-b88535fc8c05", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e38a3dd4-a316-4fb6-86d3-4d9eaf098019", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "06eddbbb-4e71-4590-bdbf-7cc57377e6d1", "text": "Vonaldiagram", "isCorrect": true}, {"id": "e2ef5136-f53b-4f5b-a8d4-dc174d2ccdfa", "text": "Kördiagram", "isCorrect": false}, {"id": "497d89e0-6585-4d5b-a5c9-c894fed86c80", "text": "Pontdiagram", "isCorrect": false}, {"id": "cbb1e156-5806-4abb-ba14-9e5b2f388aa9", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "52690ecf-2c4c-4631-99e9-debba0597e9f", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('7252676c-f205-4503-9276-48a0a9241413', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "9a93d390-baeb-4478-9e76-33059794d911", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "1e157f70-92cc-4854-b4b2-9b22b26872a2", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6bccf7b7-6ed6-4e26-a873-3aea7e6893ee", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c29d1acb-659f-4853-b83f-62bad52e44fa", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "4e7e6fa5-0408-425e-96e9-76c426001d4e", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "82b757fa-0d8d-4407-967d-888db34b277c", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "2b5eea22-20bc-455a-8f09-4bc1f3285ffd", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "32db7188-a521-4c9e-8fe7-d6c4199fe14a", "text": "Biztos esemény", "isCorrect": false}, {"id": "7f70e09e-6808-49ac-a09d-51db6bb88538", "text": "Lehetséges", "isCorrect": false}, {"id": "b7966379-3c73-4db5-9994-6c731d8390aa", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "31230797-f9e9-4f0d-9fac-c9e6596b44a3", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "dd3cccbe-2f95-496f-b2d9-bc01b1672762", "text": "Biztos esemény", "isCorrect": true}, {"id": "f0574de1-62f0-4de4-ac22-b719bcb5bbec", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "52e3fdd2-d4d6-492b-8148-0da7050cd355", "text": "Ritka", "isCorrect": false}, {"id": "9eff26a2-1abd-4fe7-b1fd-2a8bb4ab882b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9b93f0a9-a758-482f-82cb-54de5a92f3c4", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "9b77d42e-e86a-4722-83ea-4843c8bfc58f", "text": "Igaz", "isCorrect": true}, {"id": "5a35f510-b391-440e-a80c-4dde93a4cce1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b8da0f83-877f-447c-b40a-c976081019b9", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b164ed3a-bb71-4d4d-b856-48dd984969db", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "3eab9cae-55bd-4d4b-ac7f-d1a2ed258dcf", "text": "Igaz", "isCorrect": true}, {"id": "19a1ece8-8ad5-40dd-b427-d1b166486006", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());